{
 "title": "Bitsadmin Download of Suspicious Extension",
 "description": "Detects usage of bitsadmin to download a file with a suspicious extension, often associated with persistence,\n  execution, stealth, and command-and-control activities.",
 "tags": [
  "attack.t1197",
  "attack.s0190",
  "attack.t1036.003",
  "attack.t1105",
  "attack.persistence",
  "attack.execution",
  "attack.stealth",
  "attack.command-and-control"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\\\bitsadmin.exe"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "/transfer"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "re",
     "values": [
      "\\\\.(exe|dll|scr|ps1|js|vbs|bat|cmd)(\\\\s|$)"
     ]
    }
   ]
  },
  {
   "name": "condition",
   "fields": []
  }
 ],
 "condition": "selection",
 "falsepositives": [
  "Legitimate bitsadmin transfers of approved files with safe extensions."
 ],
 "level": "high"
}

