{
 "title": "Copy From Volume Shadow Copy via cmd.exe",
 "description": "Detects usage of the built-in copy command targeting a volume shadow copy, often used to copy registry hives.",
 "tags": [
  "attack.t1490",
  "attack.impact"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\cmd.exe"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "copy"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "\\\\?\\GLOBALROOT\\Device\\HarddiskVolumeShadowCopy"
     ]
    }
   ]
  }
 ],
 "condition": "selection",
 "falsepositives": [],
 "level": "high"
}

