history.rule_text:
{
 "title": "Disable Microsoft Defender Firewall via Registry",
 "description": "Detects attempts to disable Windows Defender Firewall by modifying the EnableFirewall registry value via reg.exe.",
 "tags": [
  "attack.defense-impairment",
  "attack.t1562.004",
  "attack.t1686.003"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\reg.exe"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "EnableFirewall"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "/d 0"
     ]
    }
   ]
  }
 ],
 "condition": "selection",
 "falsepositives": [
  "Legitimate administrative changes to firewall policy via registry are rare but possible."
 ],
 "level": "high"
}
